// TH16 Extra final boss spell 109 "秘儀「リバースインヴォーカー」"
// Source: st07bs.ecl.txt BossCard1:894-955 / BossCard1_at:1153-1196.

const TIME_LIMIT: int = 4324;
const OPENING_BUFFER: int = 120;

const TH16_RING_BALL2: int = 464;

// BossCard1_at EX chain: bounce once off any wall, then speed 1.5 -> 1.0 over 60f.
// The exact per-bullet post-bounce speed hook is unavailable; wait(58) approximates
// the ~50-61 frame first-wall contact from the static boss at (0,224).
xformdef REVERSE_BOUNCE {
    bounce_arm(15, 1);
    wait(58);
    set_speed(1.5fx);
    step_speed(1.0fx, 60);
}

async sub source_enemy() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);

    // BossCard1 entry state: boss enters at (0,128). movePosTime at t=4, then
    // the 90+60 frame pre-roll before the first burst at t=154.
    wait(4);
    move_to(60, 0fx, 224fx, EASE_QUAD_OUT);
    wait(90);
    wait(60);

    // BossCard1_at etNew/etSprite/etAim/etCount/etSpeed/etDist (M=1 -> speed 3.3).
    sh_reset(0);
    sh_sprite(0, TH16_RING_BALL2, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 3, 1);
    sh_speed(0, 3.3fx, 0fx);
    sh_dist(0, 24fx);
    sh_xform(0, REVERSE_BOUNCE);

    var A: angle = 90deg;
    for b in 0..1012 {
        sh_angle(0, A, 45deg);
        sh_fire(0);
        A = A - 364bam;
        if (b + 1) % 3 == 0 {
            A = A + 8192bam;
        }
        wait(4);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
